/bin/bash -lc "python -c \"
import numpy as np
d = np.load('source_pixels.npz')
rgb = d['rgb']
def ascii_map(t):
    f = rgb[t].astype(int)
    r,g,b = f[...,0],f[...,1],f[...,2]
    H,W = f.shape[:2]
    out=[]
    for y in range(0,H,4):
        row=''
        for x in range(0,W,2):
            block=f[y:y+4,x:x+2].mean(axis=(0,1))
            rr,gg,bb=block
            if gg>120 and rr>100 and bb<120 and rr>bb+40 and gg>bb+40:
                ch='T'  # tennis yellow
            elif rr>120 and gg>90 and bb<120 and rr>gg:
                ch='o'  # brown/orange wood
            elif abs(rr-gg)<20 and abs(gg-bb)<20:
                v=(rr+gg+bb)/3
                ch='.' if v>150 else ('#' if v<90 else ':')
            elif bb>rr and bb>gg:
                ch='B'
            elif gg>rr and gg>bb:
                ch='g'
            else:
                ch='?'
            row+=ch
        out.append(row)
    return '\\n'.join(out)
print(ascii_map(0))
\""
